<!DOCTYPE html>
<html>
<head>
    <meta charset='utf-8'>
    <meta http-equiv='X-UA-Compatible' content='IE=edge'>
    <title>Page Title</title>
    <meta name='viewport' content='width=device-width, initial-scale=1'>
    <script >
        function Espaces (ch){
    ch=ch.trim()
    p=ch.indexOf("  ")
    while (p!=-1){
        ch=ch.substring(0,p)+ch.substring(p+1,ch.length)
        p=ch.indexOf("  ")
    }
    ch=ch[0].toUpperCase()+ch.substr(1,ch.length-1)
    i=0
    while (i!=-1){
        i=ch.indexOf(" ",i+1)
        ch=ch.substr(0,i+1)+ch[i+1].toUpperCase()+ch.substr(i+2,ch.length-1)
    }
    return ch
    
}

function f(){
    ch=document.getElementById("ch").value;
    document.getElementById("res").value=Espaces(ch);
}

    </script>
</head>
<style>
    input{
        width: 35%;
    }
</style>
<body>
    <input type="text" name="" id="ch">
    <button onclick="f()">Afficher</button>
    <input type="text" name="" id="res">
</body>
</html>

