from numpy import array
dt = dict(j = int,
          m = int,
          a = int)
employe = dict(mat = str,
               nom = str,
               salaire = float,
               date = dt)
E = array([dict(employe)]*4)
def remplir(E,n):
    for i in range(n):
        a = False
        while not a:
            E[i]["mat"] = str(input("donner le matricule de l'employé numéro "+str(i)+": "))
            a = (E[i]["mat"].isdecimal()) and (len(E[i]["mat"]) == 10)
        a = False
        while not a:
            E[i]["nom"] = str(input("donner le nom de l'employé numéro "+str(i)+": "))
            a = len(E[i]["nom"]) <= 30
        E[i]["salaire"] = str(input("donner le salaire de l'employé numéro "+str(i)+": "))
        a = False
        while not a:
            E[i]["date"]["j"] = int(input("introduire le jour de naissance de l'employé numéro "+str(i)+": "))
            a = 1 <= E[i]["date"]["j"] <= 31
        a = False
        while not a:
            E[i]["date"]["m"] = int(input("introduire le mois de naissance de l'employé numéro "+str(i)+": "))
            a = 1 <= E[i]["date"]["m"] <= 12
        a = False
        while not a:
            E[i]["date"]["a"] = int(input("introduire l'année de naissance de l'employé numéro "+str(i)+": "))
            a = 1965 <= E[i]["date"]["a"] <= 2000
def affiche(E,n):
    for i in range(n):
        print(E[i]["mat"],"|",E[i]["nom"],"|", E[i]["salaire"],"|",E[i]["date"]["j"],"|",E[i]["date"]["m"],"|",E[i]["date"]["a"])
E = array([dict(employe)]*4)        
remplir(E,4)
print("la liste des employés est : ")
affiche(E,4)


