def remplir():
    a=win.a.text()
    b=win.b.text()
    if not(a.isdecimal() and a!="" and b!="" and b.isdecimal()):
        QMessageBox.critical(win,"","il faut taper les valeurs de a et b")
    elif not(2<=int(a)<=int(b)<= 1000):
        QMessageBox.critical(win,"","saisir incorrect")
    else:
        ft=open(np1,"w")
        ft.write(a+"  "+b+"\n")
        a = int(a)
        b = int(b)
        for i in range(a,b+1):
            D = fpremier(i)
            ft.write(str(i)+" = "+D+"\n")
        ft.close()
def fpremier(m):
    ch=""
    i=2
    while not(m==1):
        if(m%i==0):
            while(m%i==0):
                ch=ch+str(i)+"*"
                m//=i
        else:
            i=i+1
    ch=ch[:len(ch)-1]
    return ch
    
def afficher():
    win.lw.clear()
    ft=open(np1,"r")
    ch=ft.readline()
    while ch!="":
        ch=ch[0:len(ch)-1]
        win.lw.addItem(ch)
        ch=ft.readline()
    ft.close()
    
        
